  'we_are_delighted_to_welcome_all_residents_please_reach_out_to_management_for_any_facility_requests': 'నివాసితులందరినీ స్వాగతిస్తున్నందుకు మేము సంతోషిస్తున్నాము! ఏదైనా సౌకర్య అభ్యర్థనల కోసం దయచేసి నిర్వహణను సంప్రదించండి.',
