  'independence_day_celebration_15_august_2026': 'స్వాతంత్ర్య దినోత్సవ వేడుకలు – 15 ఆగస్టు 2026',
  'greenfield_heights_community_cordially_invites_all_residents_to_the_independence_day_celebration_at_the_clubhouse_main_hall_at_8_00_am': 'గ్రీన్‌ఫీల్డ్ హైట్స్ కమ్యూనిటీ ఉదయం 8:00 గంటలకు క్లబ్‌హౌస్ మెయిన్ హాల్‌లో జరిగే స్వాతంత్ర్య దినోత్సవ వేడుకలకు నివాసితులందరినీ సాదరంగా ఆహ్వానిస్తోంది.',
  'scheduled_power_outage_18_july_2026_block_b': 'షెడ్యూల్ చేయబడిన విద్యుత్ అంతరాయం – 18 జూలై 2026 (బ్లాక్ B)',
  'electrical_board_maintenance_scheduled_for_block_b_apartments_on_18_july_between_10_am_2_pm_generator_backup_will_be_available_for_common_areas': 'జూలై 18న ఉదయం 10 గంటల నుండి మధ్యాహ్నం 2 గంటల మధ్య బ్లాక్ B అపార్ట్‌మెంట్‌ల కోసం ఎలక్ట్రికల్ బోర్డు నిర్వహణ షెడ్యూల్ చేయబడింది. సాధారణ ప్రాంతాలకు జనరేటర్ బ్యాకప్ అందుబాటులో ఉంటుంది.',
